-module(bright_access_view).
-export([render/0,recovery/1]).
head(Title,Script)->[<<"<!doctype html><html lang='en'><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>">>,Title,<<" · Bright Studio</title><link rel='stylesheet' href='/studio/hub.css'><script defer src='">>,Script,<<"'></script></head>">>].
render()->[head(<<"Account access">>,<<"/studio/hub/access.js">>),<<"<body><main class='access-main'><div class='activity-bar'><a href='/studio/hub/'>Back to Studio</a><a href='/studio/hub/account/'>Account settings</a></div><p class='eyebrow'>Your account</p><h1>Access &amp; members</h1><p id='access-account'></p><p id='access-status' role='status' aria-live='polite'>Loading saved access&hellip;</p><section><h2>Active sessions</h2><p>Only this account's sessions are shown. Revoking a session signs out that browser.</p><button id='access-reload' class='secondary' type='button'>Refresh access</button><div id='access-sessions'></div><button id='access-revoke-all' class='secondary' type='button'>Sign out every session</button></section><section><h2>Workspaces</h2><p>Manage workspace membership here. Your sources, documents and device copies stay private; adding a member does not share them.</p><form id='access-create'><label>Workspace name<input id='access-title' required maxlength='200'></label><button id='access-create-button'>Create workspace</button></form><div id='access-workspaces'></div><section id='access-detail' hidden><h3 id='access-workspace-title'></h3><p id='access-members-status' role='status' aria-live='polite'></p><div id='access-members'></div><form id='access-add' hidden><label>Existing account email<input id='access-member-email' type='email' required maxlength='254'></label><label>Member role<select id='access-member-role'><option value='viewer'>Viewer</option><option value='editor'>Editor</option><option value='admin'>Admin</option></select></label><button id='access-add-button'>Add member</button></form><button id='access-members-reload' class='secondary' type='button'>Load latest membership</button></section></section><section><h2>Forgotten password</h2><p id='access-recovery-info'></p><a href='/studio/recover/'>Account recovery</a></section></main></body></html>">>].
recovery(Reset)->Title=case Reset of true-> <<"Reset password">>;false-> <<"Account recovery">> end,
 [head(Title,<<"/studio/recovery.js">>),<<"<body><main class='login'><p class='eyebrow'>Bright Studio</p><h1>">>,Title,<<"</h1><p id='recovery-status' role='status' aria-live='polite'>Checking recovery availability&hellip;</p><form id='recovery-request' hidden><label>Recovery email<input id='recovery-email' name='email' type='email' required maxlength='254' autocomplete='email'></label><button id='recovery-request-button'>Request reset link</button></form><form id='recovery-reset' hidden><label>Reset password<input id='recovery-password' type='password' required minlength='12' maxlength='1024' autocomplete='new-password'></label><label>Confirm reset password<input id='recovery-confirm' type='password' required minlength='12' maxlength='1024' autocomplete='new-password'></label><button id='recovery-reset-button'>Save new password</button></form><p><a href='/studio/login/'>Back to sign in</a></p></main></body></html>">>].
